<?php
require_once __DIR__.'/../../app/layout.php';require_role('company');$uid=(int)current_user()['id'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='toggle'){$st=db()->prepare("UPDATE jobs SET status=IF(status='Aktif','Ditangguhkan','Aktif') WHERE id=? AND company_id=?");$st->execute([(int)$_POST['job_id'],$uid]);flash('success','Status lowongan diperbarui.');redirect('company/jobs.php');}
$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$type=in_array($_POST['work_type']??'',['Remote','Hybrid','Onsite'],true)?$_POST['work_type']:'Remote';if(mb_strlen($title)<4||mb_strlen($desc)<20)$error='Judul minimal 4 karakter dan deskripsi minimal 20 karakter.';else{$st=db()->prepare("INSERT INTO jobs(company_id,title,description,requirements,skills,work_type,employment_type,location,salary_range,accessibility,deadline,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,'Aktif')");$st->execute([$uid,$title,$desc,trim($_POST['requirements']??''),trim($_POST['skills']??''),$type,trim($_POST['employment_type']??'Penuh waktu'),trim($_POST['location']??''),trim($_POST['salary_range']??''),trim($_POST['accessibility']??''),($_POST['deadline']??'')?:null]);flash('success','Lowongan berhasil dipublikasikan.');redirect('company/jobs.php');}}
$st=db()->prepare("SELECT j.*,(SELECT COUNT(*) FROM applications a WHERE a.job_id=j.id) applicants FROM jobs j WHERE company_id=? ORDER BY created_at DESC");$st->execute([$uid]);$list=$st->fetchAll();page_header('Kelola lowongan');?>
<section class="page-hero"><div class="container"><span class="eyebrow">DASHBOARD PERUSAHAAN</span><h1>Kelola lowongan kerja</h1><p>Jelaskan peran, keterampilan, dan dukungan aksesibilitas secara transparan.</p></div></section><section class="section"><div class="container two-col"><div class="panel"><h2>Publikasikan lowongan</h2><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><form method="post" class="form"><?=csrf_field()?><label>Judul posisi<input name="title" required placeholder="Junior Web Developer"></label><label>Deskripsi pekerjaan<textarea name="description" rows="5" minlength="20" required placeholder="Tanggung jawab, tujuan peran, gambaran pekerjaan..."></textarea></label><label>Kualifikasi<textarea name="requirements" rows="3"></textarea></label><label>Keterampilan (pisahkan koma)<input name="skills" placeholder="PHP, MySQL, komunikasi"></label><div class="form-row"><label>Tipe kerja<select name="work_type"><option>Remote</option><option>Hybrid</option><option>Onsite</option></select></label><label>Status kerja<select name="employment_type"><option>Penuh waktu</option><option>Paruh waktu</option><option>Kontrak</option><option>Magang</option><option>Freelance</option></select></label></div><div class="form-row"><label>Lokasi<input name="location" placeholder="Remote / kota"></label><label>Rentang gaji<input name="salary_range" placeholder="4–6 juta/bulan"></label></div><label>Akomodasi dan aksesibilitas<textarea name="accessibility" rows="3" placeholder="Wawancara daring, instruksi tertulis, akses lift..."></textarea></label><label>Batas lamaran (opsional)<input type="date" name="deadline"></label><button class="btn btn-primary full">Publikasikan lowongan</button></form></div><div class="panel"><h2>Lowonganmu (<?=count($list)?>)</h2><?php foreach($list as $j):?><article class="managed"><span class="badge <?=e(badge_class($j['status']))?>"><?=e($j['status'])?></span><h3><?=e($j['title'])?></h3><p class="muted"><?=e($j['work_type'])?> · <?=e($j['location'])?> · <?= (int)$j['applicants']?> pelamar</p><div class="actions"><a class="btn btn-outline btn-sm" href="<?=e(url('job.php?id='.(int)$j['id']))?>">Lihat</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="job_id" value="<?=(int)$j['id']?>"><button class="btn btn-outline btn-sm"><?=$j['status']==='Aktif'?'Tangguhkan':'Aktifkan'?></button></form></div></article><?php endforeach;?></div></div></section><?php page_footer();?>
